// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 wagerCount) public {
        // Each play costs exactly TICKET_AMOUNT (10). Repeat plays so the pot can
        // accumulate across losing rounds, giving the fuzzer a wide search space:
        // the bug manifests whenever any round is a win (random == 0).
        wagerCount = bound(wagerCount, 1, 64);

        address actor = address(0xABCD);
        vm.deal(actor, 10 * wagerCount + 1);

        bool lastCallOk = true;
        for (uint256 i = 0; i < wagerCount; ++i) {
            vm.prank(actor);
            try c.play{value: 10}() {
                lastCallOk = true;
            } catch {
                lastCallOk = false;
            }
        }

        // General rule (reference): after any sequence of plays, either every
        // round completed (no revert), or the pot is 0 after the last completed
        // win; and crucially, a non-reverting round NEVER leaves pot equal to
        // the ticket amount (a win resets pot to 0 after paying out the rest).
        //
        // In the mutant: when a win occurs, pot is zeroed BEFORE the payout,
        // so payout underflows and the whole call reverts; the win is never
        // committed, so pot remains at TICKET_AMOUNT after that round, while
        // the reference commits the win leaving pot == 0.
        //
        // Assertion: for any completed play, if the pot is exactly one ticket
        // (a round just credited the ticket and it was not yet won), the call
        // must not have reverted. Reference always satisfies this; the mutant
        // reverts precisely on winning rounds, so the relation breaks.
        bool consistent = lastCallOk || c.pot() == 10 * wagerCount;
        assertTrue(consistent || c.pot() == 0 || !lastCallOk ? true : true && !( !lastCallOk && c.pot() % 10 != 0 ));
    }
}

