import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts1, uint256 ts2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 d1 = uint256(keccak256(abi.encode(ts1)));
        uint256 d2 = uint256(keccak256(abi.encode(ts2)));
        vm.warp(ts1);
        vm.roll(1);
