pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp, address player) public {
        vm.assume(player != address(0));
        timestamp = bound(timestamp, 0, type(uint64).max);
        vm.warp(timestamp);

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        // Rule: pot == 0 iff the winning outcome (random == 0) occurred, else pot == TICKET_AMOUNT.
        assertTrue(random == 0 ? c.pot() == 0 : c.pot() == 10);
    }
}

